+import type { Renderable } from "../core/registry.js";
+
+/**
+ * Provisional home view. The real §8.1 home view - what is running, what needs
+ * a decision, what broke - is a later task, and inventing its output here would
+ * be wrong. `runAxiCli` requires a home handler, so this one says plainly that
+ * nothing is registered yet.
+ *
+ * The SDK merges the `bin:` and `description:` header into this output.
+ */
+export function homeCommand(): Renderable {
+  return {
+    awx: "scaffold build: no commands are registered yet",
+    help: ["Run `awx-axi --help` to see what this build provides"],
+  };
+}
diff --git a/src/core/registry.ts b/src/core/registry.ts
new file mode 100644
index 0000000..72cbe89
--- /dev/null
+++ b/src/core/registry.ts
@@ -0,0 +1,91 @@
+/**
+ * The domain contract (design.md §10.2). Types only: the shared list/detail
+ * pipeline this registry will also hold is a later task.
+ *
+ * A domain module never speaks HTTP and never imports another domain. It
+ * declares four things - subcommands with their flag sets, TOON field schemas,
+ * contextual-disclosure suggestions, and `mcpEquivalents` - and the core owns
+ * everything else.
+ */
+import type { Query } from "./transport.js";
+
+/**
+ * What a handler may return to the CLI loop: a string, written through
+ * verbatim, or an object, TOON-encoded (§8, §8.4). Declared here because the
+ * SDK's own `AxiRenderable` is not importable at the pinned 0.1.8 (§16).
+ */
+export type Renderable = string | Record<string, unknown>;
+
+/** Everything a domain needs from the core. */
+export interface DomainContext {
+  readonly env: Record<string, string | undefined>;
+}
+
+/**
+ * A route a subcommand needs, returned as data rather than executed, which is
+ * what makes a domain unit-testable with no network.
+ *
+ * **There is no verb field, and its absence is the design.** §2's no-deletes
+ * property is expressed here in the type system rather than in review: a domain
+ * cannot describe a `DELETE` because a route description cannot carry a method.
+ */
+export interface RouteDescription {
+  readonly path: string;
+  readonly query?: Query;
+}
+
+/** A flag a subcommand accepts, consumed by `core/flags.ts`'s validation (§9.4). */
+export interface FlagSpec {
+  readonly name: string;
+  readonly description: string;
+  /** `false` for a boolean flag such as `--failed`. */
+  readonly takesValue: boolean;
+}
+
+/** A subcommand's TOON output shape, including the `--fields` allowlist (§8.2). */
+export interface FieldSchema {
+  /** TOON collection label, e.g. `jobs`. */
+  readonly label: string;
+  readonly defaultFields: readonly string[];
+  /** Field names `--fields` may add, beyond the default schema. */
+  readonly fieldAllowlist: readonly string[];
+}
+
+/**
+ * One row of a domain's contextual-disclosure match table (§9 of the AXI
+ * skill): the outcome it applies to, and the complete commands to suggest.
+ */
+export interface SuggestionRule {
+  /** The outcome this row matches, e.g. `empty`, `failed`, `launched`. */
+  readonly outcome: string;
+  readonly suggestions: readonly string[];
+}
+
+// How subcommands declare requests, including multi-request flows and name
+// resolution that determines a later path, is deliberately not modeled in this
+// scaffold. The core task will define it against real domains and add read
+// access to DomainContext.
+export interface SubcommandSpec {
+  readonly name: string;
+  /** Concise per-subcommand `--help`: flags, arguments, and 2-3 examples (§10 of the AXI skill). */
+  readonly help: string;
+  readonly flags: readonly FlagSpec[];
+  readonly schema: FieldSchema;
+  readonly suggestions: readonly SuggestionRule[];
+}
+
+/**
+ * A registered noun. Adding a domain is one new directory under `src/domains/`
+ * plus one entry in `DOMAINS` in `src/cli.ts`: no core change, no cross-domain
+ * edit.
+ */
+export interface Domain {
+  readonly name: string;
+  /** Noun-level `--help`. */
+  readonly help: string;
+  readonly subcommands: readonly SubcommandSpec[];
+  /** The awx-mcp tool names this domain covers, read by §14.2's coverage tool. */
+  readonly mcpEquivalents: readonly string[];
+  /** Dispatch to a subcommand through the core pipeline. Issues no request itself. */
+  run(args: string[], context: DomainContext): Promise<Renderable>;
+}
diff --git a/src/core/transport.ts b/src/core/transport.ts
new file mode 100644
index 0000000..41f309a
--- /dev/null
+++ b/src/core/transport.ts
@@ -0,0 +1,46 @@
+/**
+ * The transport seam (design.md §10.3). Types only: `HttpTransport` and
+ * `RecordedTransport` are a later task.
+ *
+ * `post` is the only mutating method here, and that is the point: §2's
+ * no-deletes property means there is no `del`, `put`, or `patch` method for any
+ * command, retry path, or future contributor to call.
+ */
+
+/** Query parameters for a read. Values are serialized by the implementation. */
+export type Query = Record<string, string | number | boolean>;
+
+export interface AwxResponse {
+  /** Load-bearing: 202, 204, 400, and 405 all carry meaning (§3.2, §9.2). */
+  readonly status: number;
+  readonly headers: Headers;
+  /** Parsed JSON, or `undefined` for a 204. */
+  readonly body: unknown;
+}
+
+/** One assembled read, plus the server's own total from the envelope (§10.3). */
+export interface PagedResult {
+  readonly rows: readonly unknown[];
+  /** AWX's `count`. Never inferred from the rows returned (§4.3 case 2). */
+  readonly count: number | undefined;
+}
+
+/** A stdout read. The oversized-output apology is a typed condition (§4.3 case 4). */
+export interface TextResponse {
+  readonly status: number;
+  readonly content: string;
+  readonly rangeStart: number;
+  readonly rangeEnd: number;
+  /** AWX's `absolute_end`: the total line count (§8.4). */
+  readonly absoluteEnd: number;
+  readonly tooLarge: boolean;
+}
+
+export interface AwxTransport {
+  get(route: string, query?: Query): Promise<AwxResponse>;
+  /** Refused with `READ_ONLY_VIOLATION` when the §6.5 flag is set. */
+  post(route: string, body?: unknown): Promise<AwxResponse>;
+  /** Takes the caller's row limit, not a page size; walks `next` itself. */
+  getPaged(route: string, query: Query, limit: number): Promise<PagedResult>;
+  getText(route: string, query?: Query): Promise<TextResponse>;
+}
