@@ -0,0 +1,79 @@
+import { describe, expect, it } from "vitest";
+
+import { DESCRIPTION, DOMAINS, main } from "../src/cli.js";
+import type { Domain } from "../src/core/registry.js";
+
+function capture(): { write: (chunk: string) => void; text: () => string } {
+  const chunks: string[] = [];
+  return {
+    write: (chunk) => {
+      chunks.push(chunk);
+    },
+    text: () => chunks.join(""),
+  };
+}
+
+describe("the CLI shell", () => {
+  it("renders the top-level help for --help", async () => {
+    const stdout = capture();
+
+    await main({ argv: ["--help"], stdout, env: {} });
+
+    expect(stdout.text()).toContain(`description: ${DESCRIPTION}`);
+    expect(stdout.text()).toContain("awx-axi <command> [args] [flags]");
+    expect(stdout.text()).toContain(
+      'domains: "none yet: this build is the scaffold"',
+    );
+  });
+
+  it("renders the version for --version", async () => {
+    const stdout = capture();
+
+    await main({ argv: ["--version"], stdout, env: {} });
+
+    expect(stdout.text().trim()).toMatch(/^\d+\.\d+\.\d+$/);
+  });
+
+  it("renders subcommand help and falls back to noun help", async () => {
+    const domains = DOMAINS as Domain[];
+    domains.push({
+      name: "job",
+      help: "job help",
+      subcommands: [
+        {
+          name: "list",
+          help: "job list help",
+          flags: [],
+          schema: { label: "jobs", defaultFields: [], fieldAllowlist: [] },
+          suggestions: [],
+        },
+      ],
+      mcpEquivalents: [],
+      run: () => Promise.resolve({}),
+    });
+
+    try {
+      const subcommandStdout = capture();
+      await main({
+        argv: ["job", "list", "--help"],
+        stdout: subcommandStdout,
+        env: {},
+      });
+      expect(subcommandStdout.text()).toContain("job list help");
+
+      const nounStdout = capture();
+      await main({
+        argv: ["job", "unknown", "--help"],
+        stdout: nounStdout,
+        env: {},
+      });
+      expect(nounStdout.text()).toContain("job help");
+    } finally {
+      domains.pop();
+    }
+  });
+
+  it("registers no domains yet", () => {
+    expect(DOMAINS).toHaveLength(0);
+  });
+});
diff --git a/test/no-delete.test.ts b/test/no-delete.test.ts
new file mode 100644
index 0000000..4de2fe3
--- /dev/null
+++ b/test/no-delete.test.ts
@@ -0,0 +1,55 @@
+import { describe, expect, it } from "vitest";
+
+import type { RouteDescription } from "../src/core/registry.js";
+import type { AwxTransport } from "../src/core/transport.js";
+
+/**
+ * The compile-time no-delete property (design.md §2, §10.2, §10.3).
+ *
+ * These assertions are checked by `npm run typecheck`, which CI runs: a failure
+ * is a type error at build time, not a failed expectation at run time. The
+ * runtime cases below exist so the property is named in the test report too.
+ */
+type Expect<T extends true> = T;
+type Equal<A, B> =
+  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2
+    ? true
+    : false;
+type HasAny<T, K extends PropertyKey> = [Extract<keyof T, K>] extends [never]
+  ? false
+  : true;
+
+// `post` is the only mutating method on the seam: there is no `del`, `put`, or
+// `patch` for any command or future contributor to call.
+type _NoMutatorsBeyondPost = Expect<
+  Equal<HasAny<AwxTransport, "delete" | "del" | "put" | "patch">, false>
+>;
+type _TransportSurfaceIsClosed = Expect<
+  Equal<keyof AwxTransport, "get" | "post" | "getPaged" | "getText">
+>;
+
+// A route description carries no HTTP verb, so a domain cannot describe a
+// DELETE even by mistake.
+type _RouteCarriesNoVerb = Expect<
+  Equal<HasAny<RouteDescription, "method" | "verb" | "httpMethod">, false>
+>;
+type _RouteSurfaceIsClosed = Expect<Equal<keyof RouteDescription, "path" | "query">>;
+
+describe("the no-delete property", () => {
+  it("exposes no delete, put, or patch on the transport", () => {
+    const surface: Array<keyof AwxTransport> = [
+      "get",
+      "post",
+      "getPaged",
+      "getText",
+    ];
+
+    expect(surface).toHaveLength(4);
+  });
+
+  it("carries no HTTP verb on a route description", () => {
+    const surface: Array<keyof RouteDescription> = ["path", "query"];
+
+    expect(surface).toHaveLength(2);
+  });
+});
